            if c - lo >= 2:
                runs.append(("h", r, lo, c))
    for c in (0, w - 1):
        r = 0
        while r < h:
            if grid[r][c] == bg:
                r += 1
                continue
            color, lo = grid[r][c], r
            while r < h and grid[r][c] == color:
                r += 1
            if r - lo >= 2:
                runs.append(("v", c, lo, r))
    bar_cells = set()
    for axis, fixed, lo, hi in runs:
        if axis == "h":
            bar_cells.update((fixed, c) for c in range(lo, hi))
        else:
            bar_cells.update((r, fixed) for r in range(lo, hi))
    markers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] != bg and (r, c) not in bar_cells]
    if not runs or not markers:
        return out
    marker = Counter(color for _, _, color in markers).most_common(1)[0][0]

    def cast(r, c, dr, dc):
        while 0 <= r < h and 0 <= c < w:
            value = grid[r][c]
            if value == marker:
                out[r][c] = 4
                return
            if value != bg:
                return
            out[r][c] = marker
            r += dr
            c += dc

    # The stripe launches as many adjacent rays as there are interior marker
